194 |     let (max_lines, max_bytes) = options.resolve();
195 |     let total_bytes = content.len();
196 |     let lines = split_lines_for_counting(content);
197 |     let total_lines = lines.len();
198 | 
199 |     if total_lines <= max_lines && total_bytes <= max_bytes {
200 |         return TruncationResult::not_truncated(content.to_string(), max_lines, max_bytes);
201 |     }
202 | 
203 |     let mut output_lines_arr: Vec<&str> = Vec::new();
204 |     let mut output_bytes_count = 0usize;
205 |     let mut truncated_by: Option<TruncationLimit> = None;
206 |     let mut last_line_partial = false;
207 | 
208 |     let mut i = lines.len() as isize - 1;
209 |     while i >= 0 && output_lines_arr.len() < max_lines {
210 |         let idx = i as usize;
211 |         // +1 byte for the '\n' separator BEFORE this line when it's not the
212 |         // first element added (i.e., when there's already a line after it).
213 |         let line_bytes = lines[idx].len() + if output_lines_arr.is_empty() { 0 } else { 1 };
214 |         if output_bytes_count + line_bytes > max_bytes {
215 |             truncated_by = Some(TruncationLimit::Bytes);
216 |             if output_lines_arr.is_empty() {
217 |                 // Edge case: the final line alone exceeds max_bytes → take a
218 |                 // partial end of it (char-boundary-snapped).
219 |                 let partial = trim_to_last_utf8_bytes(lines[idx], max_bytes);
220 |                 output_lines_arr.insert(0, partial);
221 |                 output_bytes_count = partial.len();
222 |                 last_line_partial = true;
223 |             }
224 |             break;
225 |         }
226 |         output_lines_arr.insert(0, lines[idx]);
227 |         output_bytes_count += line_bytes;
228 |         i -= 1;
229 |     }
230 | 
231 |     if output_lines_arr.len() >= max_lines && output_bytes_count <= max_bytes {
232 |         truncated_by = Some(TruncationLimit::Lines);
233 |     }
