442 |     let new_lines: Vec<&str> = new_content.split('\n').collect();
443 |     let max_line_num = old_lines.len().max(new_lines.len());
444 |     let line_num_width = max_line_num.to_string().len();
445 | 
446 |     let mut out: Vec<String> = Vec::new();
447 |     let mut old_line_num = 1usize;
448 |     let mut new_line_num = 1usize;
449 |     let mut last_was_change = false;
450 |     let mut first_changed_line: Option<usize> = None;
451 | 
452 |     for (i, op) in ops.iter().enumerate() {
453 |         let tag = op.tag();
454 |         // The raw lines for this op — sliced from the op ranges directly
455 |         // (mirrors TS `part.value.split("\n")` + trailing-empty pop).
456 |         let mut raw: Vec<&str> = match tag {
457 |             similar::DiffTag::Equal | similar::DiffTag::Delete => {
458 |                 old_lines[op.old_range().start..op.old_range().end].to_vec()
459 |             }
460 |             _ => new_lines[op.new_range().start..op.new_range().end].to_vec(),
461 |         };
462 |         if raw.last().map(|s| s.is_empty()).unwrap_or(false) {
463 |             raw.pop();
464 |         }
465 |         let raw_len = raw.len();
466 | 
467 |         let is_added = matches!(tag, similar::DiffTag::Insert | similar::DiffTag::Replace);
468 |         let is_removed = matches!(tag, similar::DiffTag::Delete | similar::DiffTag::Replace);
469 | 
470 |         if is_added || is_removed {
471 |             if first_changed_line.is_none() {
472 |                 first_changed_line = Some(new_line_num);
473 |             }
474 |             for line in &raw {
475 |                 if is_added {
476 |                     out.push(format!(
477 |                         "+{:>width$} {}",
478 |                         new_line_num,
479 |                         line,
480 |                         width = line_num_width
481 |                     ));
482 |                     new_line_num += 1;
483 |                 }
484 |                 if is_removed {
485 |                     out.push(format!(
486 |                         "-{:>width$} {}",
487 |                         old_line_num,
488 |                         line,
489 |                         width = line_num_width
490 |                     ));
491 |                     old_line_num += 1;
492 |                 }
493 |             }
494 |             // A `Replace` op iterates both add and remove above; for pure
495 |             // Insert/Delete only one branch fires. Leave last_was_change set.
496 |             last_was_change = true;
497 |             let _ = i; // index only needed for context lookahead below
498 |         } else {
499 |             // Equal → context lines, show a few before/after changes.
500 |             let next_is_change = i + 1 < ops.len()
501 |                 && matches!(
502 |                     ops[i + 1].tag(),
503 |                     similar::DiffTag::Insert | similar::DiffTag::Delete | similar::DiffTag::Replace
504 |                 );
505 |             let has_leading_change = last_was_change;
506 |             let has_trailing_change = next_is_change;
507 | 
508 |             if has_leading_change && has_trailing_change {
509 |                 if raw_len <= context_lines * 2 {
510 |                     for line in &raw {
511 |                         out.push(format!(
512 |                             " {:>width$} {}",
513 |                             old_line_num,
514 |                             line,
515 |                             width = line_num_width
516 |                         ));
517 |                         old_line_num += 1;
518 |                         new_line_num += 1;
519 |                     }
520 |                 } else {
521 |                     let leading = &raw[..context_lines];
522 |                     let trailing = &raw[raw_len - context_lines..];
523 |                     let skipped = raw_len - leading.len() - trailing.len();
524 |                     for line in leading {
525 |                         out.push(format!(
526 |                             " {:>width$} {}",
527 |                             old_line_num,
528 |                             line,
529 |                             width = line_num_width
530 |                         ));
531 |                         old_line_num += 1;
532 |                         new_line_num += 1;
533 |                     }
534 |                     out.push(format!(" {:>width$} ...", "", width = line_num_width));
535 |                     old_line_num += skipped;
536 |                     new_line_num += skipped;
537 |                     for line in trailing {
538 |                         out.push(format!(
539 |                             " {:>width$} {}",
540 |                             old_line_num,
541 |                             line,
542 |                             width = line_num_width
543 |                         ));
544 |                         old_line_num += 1;
545 |                         new_line_num += 1;
546 |                     }
547 |                 }
548 |             } else if has_leading_change {
549 |                 let shown = if raw_len <= context_lines {
550 |                     &raw[..]
551 |                 } else {
552 |                     &raw[..context_lines]
553 |                 };
554 |                 let skipped = raw_len - shown.len();
555 |                 for line in shown {
556 |                     out.push(format!(
557 |                         " {:>width$} {}",
558 |                         old_line_num,
559 |                         line,
560 |                         width = line_num_width
561 |                     ));
562 |                     old_line_num += 1;
563 |                     new_line_num += 1;
564 |                 }
565 |                 if skipped > 0 {
566 |                     out.push(format!(" {:>width$} ...", "", width = line_num_width));
567 |                     old_line_num += skipped;
568 |                     new_line_num += skipped;
569 |                 }
570 |             } else if has_trailing_change {
571 |                 let skipped = raw_len.saturating_sub(context_lines);
572 |                 if skipped > 0 {
573 |                     out.push(format!(" {:>width$} ...", "", width = line_num_width));
574 |                     old_line_num += skipped;
575 |                     new_line_num += skipped;
576 |                 }
577 |                 for line in &raw[skipped..] {
578 |                     out.push(format!(
579 |                         " {:>width$} {}",
580 |                         old_line_num,
581 |                         line,
582 |                         width = line_num_width
583 |                     ));
584 |                     old_line_num += 1;
585 |                     new_line_num += 1;
586 |                 }
587 |             } else {
588 |                 // Skip these context lines entirely.
589 |                 old_line_num += raw_len;
590 |                 new_line_num += raw_len;
591 |             }
592 |             last_was_change = false;
593 |         }
594 |     }
595 | 
