218 |     /// Find a match in the text and create a hit.
219 |     fn find_match(
220 |         &self,
221 |         session_id: &str,
222 |         entry_id: &str,
223 |         role: &str,
224 |         text: &str,
225 |         query_lower: &str,
226 |     ) -> Option<SessionSearchHit> {
227 |         let text_lower = text.to_lowercase();
228 |         if let Some(position) = text_lower.find(query_lower) {
229 |             // Extract a snippet around the match
230 |             let snippet = self.extract_snippet(text, position, query_lower.len());
231 | 
232 |             // Calculate a simple relevance score
233 |             // More matches = higher score, earlier position = higher score
234 |             let match_count = text_lower.matches(query_lower).count();
235 |             let position_factor = 1.0 - (position as f64 / text.len() as f64).min(1.0);
236 |             let score = (match_count as f64) * (0.5 + 0.5 * position_factor);
237 | 
238 |             Some(SessionSearchHit {
239 |                 session_id: session_id.to_string(),
240 |                 entry_id: entry_id.to_string(),
241 |                 role: role.to_string(),
242 |                 snippet,
243 |                 match_position: position,
244 |                 score,
245 |             })
246 |         } else {
247 |             None
248 |         }
249 |     }
