254 |         let start = position.saturating_sub(context_chars);
255 |         let end = (position + match_len + context_chars).min(text.len());
256 | 
257 |         let mut snippet = String::new();
258 |         if start > 0 {
259 |             snippet.push_str("...");
260 |         }
261 |         snippet.push_str(&text[start..end]);
262 |         if end < text.len() {
263 |             snippet.push_str("...");
264 |         }
265 | 
