795 | /// A reload-signal mail slot (B5d). The reload callback (built by
796 | /// [`reload_callback_from_mailbox`]) captures a clone; the TUI installs a
797 | /// `tokio` unbounded sender after it starts. When a plugin calls
798 | /// `runtime_action(Reload)`, the callback signals `()` (if a TUI is installed)
799 | /// and the TUI performs the reload **asynchronously** — the plugin's call
800 | /// returns `Ok(null)` immediately, so the calling plugin's cdylib is NOT
801 | /// unmapped while its `runtime_action` frame is still on the stack (the reload,
802 | /// which drops the old keepalive, happens after the call returns). This breaks
803 | /// the self-unmapping race a synchronous plugin-initiated reload would have.
804 | ///
805 | /// ice-extensions carries only `()` (no pi-cli `TuiMessage` type) — preserving
806 | /// the leaf DAG. The TUI owns the receiver + the actual reload routine.
807 | #[derive(Clone)]
808 | pub struct ReloadMailbox {
809 |     tx: Arc<std::sync::Mutex<Option<tokio::sync::mpsc::UnboundedSender<()>>>>,
810 | }
811 | 
812 | impl Default for ReloadMailbox {
813 |     fn default() -> Self {
814 |         Self {
815 |             tx: Arc::new(std::sync::Mutex::new(None)),
816 |         }
817 |     }
818 | }
819 | 
820 | impl ReloadMailbox {
821 |     /// A fresh empty mail slot (no TUI installed yet).
822 |     pub fn new() -> Self {
823 |         Self::default()
824 |     }
825 | 
826 |     /// Install the TUI's reload-signal sender (after the TUI starts). Replaces
827 |     /// any prior sender. The TUI drops the receiver on shutdown; a sender held
828 |     /// here keeps the channel half-open, so [`clear`] on shutdown is advised.
829 |     pub fn install(&self, tx: tokio::sync::mpsc::UnboundedSender<()>) {
830 |         *self.tx.lock().unwrap() = Some(tx);
831 |     }
832 | 
833 |     /// Signal a reload (plugin-initiated via `runtime_action(Reload)`).
834 |     /// `Ok(())` if a TUI is installed (the signal was enqueued; the TUI may
835 |     /// still be mid-reload). `Err(())` if no TUI is installed (the host returns
836 |     /// a "reload not available" error to the plugin).
837 |     pub fn signal(&self) -> Result<(), ()> {
838 |         let g = self.tx.lock().unwrap();
839 |         match &*g {
840 |             Some(tx) => {
841 |                 let _ = tx.send(());
842 |                 Ok(())
843 |             }
844 |             None => Err(()),
845 |         }
846 |     }
847 | 
848 |     /// Drop the installed sender (TUI shutdown). Idempotent.
849 |     pub fn clear(&self) {
850 |         *self.tx.lock().unwrap() = None;
851 |     }
852 | }
