441 | /// Run a single assistant-producing call with bounded retry on transient
442 | /// errors. Mirrors `retryAssistantCall`: aborts are terminal (never retried);
443 | /// success returns; non-retryable or exhausted returns the final error;
444 | /// otherwise exponential backoff `base_delay_ms * 2^(attempt-1)`, with the
445 | /// sleep honoring `signal` — an abort during sleep is normalized to an aborted
446 | /// `AssistantMessage` (matching TS's `stopReason:"aborted"` normalization).
447 | async fn retry_assistant_call<F, Fut>(
448 |     produce: F,
449 |     retry: Option<RetryPolicy>,
450 |     signal: &CancellationToken,
451 | ) -> AssistantMessage
452 | where
453 |     F: Fn() -> Fut,
454 |     Fut: std::future::Future<Output = AssistantMessage>,
455 | {
456 |     let policy = retry.filter(|p| p.enabled);
457 |     let max_attempts: u32 = policy.as_ref().map(|p| p.max_retries).unwrap_or(0);
458 |     let base_delay_ms: u64 = policy.as_ref().map(|p| p.base_delay_ms).unwrap_or(1000);
459 |     let max_agent_delay_ms: u64 = policy
460 |         .as_ref()
461 |         .map(|p| p.max_agent_delay_ms)
462 |         .unwrap_or(60_000);
463 | 
464 |     let mut attempt: u32 = 0;
465 |     loop {
466 |         let response = produce().await;
467 | 
468 |         // Abort: terminal but not successful; never retry.
469 |         if response.stop_reason == StopReason::Aborted {
470 |             return response;
471 |         }
472 |         // Success: non-error, non-abort.
473 |         if response.stop_reason != StopReason::Error {
474 |             return response;
475 |         }
476 |         // Non-retryable or budget exhausted: return the final error.
477 |         if attempt >= max_attempts || !is_retryable_assistant_error(&response) {
478 |             return response;
479 |         }
480 |         attempt += 1;
481 |         let delay_ms = base_delay_ms
482 |             .saturating_mul(1u64 << (attempt - 1))
483 |             .min(max_agent_delay_ms);
484 |         // Sleep honoring cancellation → normalize to aborted.
485 |         tokio::select! {
486 |             _ = tokio::time::sleep(Duration::from_millis(delay_ms)) => {}
487 |             _ = signal.cancelled() => {
488 |                 let mut aborted = response;
489 |                 aborted.stop_reason = StopReason::Aborted;
490 |                 aborted.error_message = None;
491 |                 return aborted;
492 |             }
493 |         }
494 |     }

