718 | pub async fn run_mapper<F>(
719 |     stream: &mut SseEventStream,
720 |     prod: &mut AssistantMessageEventStreamProducer,
721 |     state: &mut MapperState,
722 |     cost_fn: F,
723 | ) where
724 |     F: Fn(&Usage) -> UsageCost,
725 | {
726 |     loop {
727 |         match stream.next_event().await {
728 |             Ok(None) => break,
729 |             Ok(Some(sse_frame)) => {
730 |                 let event =
731 |                     match crate::providers::anthropic::sse::parse_anthropic_event(&sse_frame) {
732 |                         Ok(e) => e,
733 |                         Err(err) => {
734 |                             emit_terminal_error(prod, state, err.to_string(), false);
735 |                             return;
736 |                         }
737 |                     };
738 |                 if let Err(err) = state.apply(&event, prod) {
739 |                     emit_terminal_error(prod, state, err.to_string(), false);
740 |                     return;
741 |                 }
742 |                 // `message_stop` is Anthropic's protocol-level terminal
743 |                 // marker.  A few proxies leave the HTTP body open or emit an
744 |                 // invalid trailing chunk after this frame; waiting for EOF
745 |                 // would turn an otherwise complete answer into an SSE/body
746 |                 // error.  The event has already carried the final stop/usage
747 |                 // state, so finalize immediately and drop the body stream.
748 |                 if event.event_type() == Some("message_stop") {
749 |                     finalize_mapper(prod, state, cost_fn);
750 |                     return;
751 |                 }
752 |             }
753 |             Err(err) => {
754 |                 let aborted = matches!(err, AiError::Abort { .. });
755 |                 emit_terminal_error(prod, state, err.to_string(), aborted);
756 |                 return;
757 |             }
758 |         }
759 |     }
760 | 
761 |     finalize_mapper(prod, state, cost_fn);
762 | }
763 | 
764 | /// Emit the terminal `Done`/`Error` event for a normally-ended stream. Mirrors
765 | /// the TS post-loop checks (lines 747-759): `pending` stop reason → error;
766 | /// `aborted`/`error` → error with the carried message; otherwise `done` with
767 | /// the model-aware cost applied.
768 | ///
769 | /// Extracted from [`run_mapper`] so tests can drive the mapper over a
770 | /// pre-decoded `Vec<AnthropicEvent>` (no `reqwest::Response` needed) and still
771 | /// exercise the terminal logic.
772 | pub fn finalize_mapper<F>(
773 |     prod: &mut AssistantMessageEventStreamProducer,
774 |     state: &mut MapperState,
775 |     cost_fn: F,
776 | ) where
777 |     F: Fn(&Usage) -> UsageCost,
778 | {
779 |     // A stream that reached the protocol's terminal `message_stop` without a
780 |     // `message_delta` is a normal stop — some proxy gateways (e.g. the
781 |     // anthropic-messages endpoints of DeepSeek/GLM relays) omit `message_delta`
782 |     // entirely. The TS check throws "Anthropic stream ended without a stop
783 |     // reason" here, which would reject those gateways; v1 defaults the still-
784 |     // `Pending` stop reason to a normal `Stop` instead (documented divergence —
785 |     // a completed `message_stop` is authoritative, and `message_delta` only
786 |     // carries usage + stop_reason). The Pending-error is preserved for streams
787 |     // that end WITHOUT `message_stop` (the SSE closed early).
788 |     if state.output.stop_reason == StopReason::Pending && state.saw_message_end {
789 |         state.output.stop_reason = StopReason::Stop;
790 |     }
791 |     if state.output.stop_reason == StopReason::Pending {
792 |         emit_terminal_error(
793 |             prod,
794 |             state,
795 |             "Anthropic stream ended without a stop reason".to_string(),
796 |             false,
797 |         );
798 |         return;
799 |     }
800 |     if matches!(
801 |         state.output.stop_reason,
802 |         StopReason::Aborted | StopReason::Error
803 |     ) {
804 |         let aborted = matches!(state.output.stop_reason, StopReason::Aborted);
805 |         let msg = state
806 |             .output
807 |             .error_message
808 |             .clone()
809 |             .unwrap_or_else(|| "An unknown error occurred".to_string());
810 |         emit_terminal_error(prod, state, msg, aborted);
811 |         return;
812 |     }
813 | 
814 |     // Success terminal. Apply the model-aware cost last.
815 |     state.output.usage.cost = cost_fn(&state.output.usage);
816 |     let reason = match state.output.stop_reason {
817 |         StopReason::Stop => DoneReason::Stop,
818 |         StopReason::Length => DoneReason::Length,
819 |         StopReason::ToolUse => DoneReason::ToolUse,
820 |         StopReason::Deferred => DoneReason::Deferred,
821 |         _ => DoneReason::Stop, // unreachable given the checks above.
822 |     };
823 |     prod.push(AssistantMessageEvent::Done {
824 |         reason,
825 |         message: state.output.clone(),
826 |     });
827 | }

