170 |     /// Apply one decoded Anthropic event. Mirrors the per-`event.type` dispatch
171 |     /// in the TS `stream` async IIFE. Returns `Err(AiError)` only on
172 |     /// unrecoverable mapper state (an unexpected block kind for a delta); SSE
173 |     /// parse errors surface earlier, in the decoder. Never panics: a missing
174 |     /// block for an index is a no-op (the TS `findIndex` returns -1 and the
175 |     /// delta is skipped).
176 |     pub fn apply(
177 |         &mut self,
178 |         event: &AnthropicEvent,
179 |         prod: &mut AssistantMessageEventStreamProducer,
180 |     ) -> Result<(), AiError> {
181 |         let AnthropicEvent::Message {
182 |             event_type,
183 |             payload,
184 |         } = event
185 |         else {
186 |             return Ok(()); // Skipped events are a mapper no-op.
187 |         };
188 | 
189 |         // The TS loop only enters the match arms for event names it recognizes;
190 |         // `iterate_anthropic_events` already filtered to ANTHROPIC_MESSAGE_EVENTS,
191 |         // so we dispatch on the payload `type` (which equals the SSE event name).
192 |         match event_type.as_str() {
193 |             "message_start" => self.apply_message_start(payload, prod),
194 |             "content_block_start" => self.apply_content_block_start(payload, prod),
195 |             "content_block_delta" => self.apply_content_block_delta(payload, prod)?,
196 |             "content_block_stop" => self.apply_content_block_stop(payload, prod),
197 |             "message_delta" => self.apply_message_delta(payload, prod),
198 |             "message_stop" => self.saw_message_end = true,
199 |             _ => {}
200 |         }
201 |         Ok(())
202 |     }
203 | 
204 |     fn apply_message_start(
205 |         &mut self,
206 |         payload: &serde_json::Value,
207 |         prod: &mut AssistantMessageEventStreamProducer,
208 |     ) {
209 |         self.ensure_started(prod);
210 |         // `event.message.id` — response id.
211 |         if let Some(id) = payload
212 |             .pointer("/message/id")
213 |             .and_then(|v| v.as_str())
214 |             .map(|s| s.to_string())
215 |         {
216 |             self.output.response_id = Some(id);
217 |         }
218 | 
219 |         // Initial usage (input/cacheRead/cacheWrite; output may be 0 here and
220 |         // updated on the final message_delta). Preserves input_tokens from
221 |         // message_start when a proxy omits it in message_delta.
222 |         if let Some(usage) = payload.pointer("/message/usage") {
223 |             let input = usage
224 |                 .get("input_tokens")
225 |                 .and_then(|v| v.as_i64())
226 |                 .unwrap_or(0);
227 |             let output = usage
228 |                 .get("output_tokens")
229 |                 .and_then(|v| v.as_i64())
230 |                 .unwrap_or(0);
231 |             let cache_read = usage
232 |                 .get("cache_read_input_tokens")
233 |                 .and_then(|v| v.as_i64())
234 |                 .unwrap_or(0);
235 |             let cache_write = usage
236 |                 .get("cache_creation_input_tokens")
237 |                 .and_then(|v| v.as_i64())
238 |                 .unwrap_or(0);
239 |             // `cache_creation.ephemeral_1h_input_tokens` — the subset of
240 |             // cache_creation written with 1h retention (cost calculation
241 |             // charges these at 2× input).
242 |             let cache_write_1h = usage
243 |                 .pointer("/cache_creation/ephemeral_1h_input_tokens")
244 |                 .and_then(|v| v.as_i64())
245 |                 .unwrap_or(0);
246 |             self.output.usage.input = input;
247 |             self.output.usage.output = output;
248 |             self.output.usage.cache_read = cache_read;
249 |             self.output.usage.cache_write = cache_write;
250 |             self.output.usage.cache_write_1h = if cache_write_1h > 0 {
251 |                 Some(cache_write_1h)
252 |             } else {
253 |                 None
254 |             };
255 |             // Anthropic doesn't report total_tokens; compute from components
256 |             // (mirrors the TS `input + output + cacheRead + cacheWrite` line).
257 |             self.output.usage.total_tokens = input + output + cache_read + cache_write;
258 |             // Cost is recomputed in the provider after the model is known; the
259 |             // mapper zeroes cost here so the provider's final pass owns it.
260 |             self.output.usage.cost = UsageCost::default();
261 |         }
262 |     }
