403 |     fn apply_content_block_delta(
404 |         &mut self,
405 |         payload: &serde_json::Value,
406 |         prod: &mut AssistantMessageEventStreamProducer,
407 |     ) -> Result<(), AiError> {
408 |         let anthropic_index = payload.get("index").and_then(|v| v.as_i64()).unwrap_or(0);
409 |         let Some(delta) = payload.get("delta") else {
410 |             return Ok(());
411 |         };
412 |         let delta_type = delta.get("type").and_then(|v| v.as_str()).unwrap_or("");
413 | 
414 |         let Some(scratch_index) = self.find_block_by_anthropic_index(anthropic_index) else {
415 |             // Delta for an unknown index (block_start missed/truncated) — skip
416 |             // rather than panic, matching the TS `if (block && ...)` guards.
417 |             return Ok(());
418 |         };
419 |         // Only the tool-call arm needs the scratch buffer, and `flush_pending`
420 |         // needs `&mut self` — so read the two scalars here and take the buffer
421 |         // borrow inside that arm instead of holding one across the whole match.
422 |         let content_index = self.blocks[scratch_index].content_index;
423 |         let block_kind = self.blocks[scratch_index].kind;
424 | 
425 |         match (block_kind, delta_type) {
426 |             (BlockKind::Text, "text_delta") => {
427 |                 let text = delta
428 |                     .get("text")
429 |                     .and_then(|v| v.as_str())
430 |                     .unwrap_or("")
431 |                     .to_string();
432 |                 if let Some(Content::Text(slot)) = self.output.content.get_mut(content_index) {
433 |                     slot.text.push_str(&text);
434 |                 }
435 |                 // Batch: `partial` is a full message clone per event.
436 |                 self.pending_text_index = Some(content_index);
437 |                 self.pending_text.push_str(&text);
438 |                 if self.should_flush(&self.pending_text) {
439 |                     self.flush_text(prod);
440 |                 }
441 |             }
442 |             (BlockKind::Thinking { redacted: false }, "thinking_delta") => {
443 |                 let thinking = delta
444 |                     .get("thinking")
445 |                     .and_then(|v| v.as_str())
446 |                     .unwrap_or("")
447 |                     .to_string();
448 |                 if let Some(Content::Thinking(slot)) = self.output.content.get_mut(content_index) {
449 |                     slot.thinking.push_str(&thinking);
450 |                 }
451 |                 // Keep channel order strict: text already streamed must reach the
452 |                 // consumer before the first thinking delta of a new block.
453 |                 self.flush_text(prod);
454 |                 self.pending_thinking_index = Some(content_index);
455 |                 self.pending_thinking.push_str(&thinking);
456 |                 if self.should_flush(&self.pending_thinking) {
457 |                     self.flush_thinking(prod);
458 |                 }
459 |             }
460 |             (BlockKind::Thinking { redacted: false }, "signature_delta") => {
461 |                 // Append to the existing signature (initializing empty to "").
462 |                 let sig = delta
463 |                     .get("signature")
464 |                     .and_then(|v| v.as_str())
465 |                     .unwrap_or("")
466 |                     .to_string();
467 |                 if let Some(Content::Thinking(slot)) = self.output.content.get_mut(content_index) {
468 |                     let current = slot.thinking_signature.take().unwrap_or_default();
469 |                     slot.thinking_signature = Some(format!("{current}{sig}"));
470 |                 }
471 |             }
472 |             (BlockKind::ToolCall, "input_json_delta") => {
473 |                 let partial = delta
474 |                     .get("partial_json")
475 |                     .and_then(|v| v.as_str())
476 |                     .unwrap_or("")
477 |                     .to_string();
478 |                 // A tool-call block is a new channel; flush what is batched so
479 |                 // the consumer never sees tool events before the text that
480 |                 // preceded them.
481 |                 self.flush_pending(prod);
482 |                 let scratch = &mut self.blocks[scratch_index];
483 |                 scratch.partial_json.push_str(&partial);
484 |                 // Re-parse the accumulated partial JSON on every delta so the
485 |                 // partial assistant message renders args live. Mirrors the TS
486 |                 // `block.arguments = parseStreamingJson(block.partialJson)`.
487 |                 let arguments = parse_streaming_json(Some(&scratch.partial_json));
488 |                 if let Some(Content::ToolCall(slot)) = self.output.content.get_mut(content_index) {
489 |                     slot.arguments = arguments;
490 |                 }
491 |                 prod.push(AssistantMessageEvent::ToolCallDelta {
492 |                     content_index,
493 |                     delta: partial,
494 |                     partial: Arc::new(self.output.clone()),
495 |                 });
496 |             }
497 |             // Redacted-thinking blocks receive no deltas; unknown delta types
498 |             // are ignored (forward-compat for future delta variants).
499 |             _ => {}
500 |         }
501 |         Ok(())
502 |     }
