511 |             return;
512 |         };
513 |         // Block boundary: emit the batched tail before the `*End` event that
514 |         // closes the block, otherwise the tail would be visible in the final
515 |         // message but never in the delta stream. Must happen before `scratch`
516 |         // takes its mutable borrow of `self.blocks`.
517 |         self.flush_pending(prod);
518 |         let scratch = &mut self.blocks[scratch_index];
519 |         let content_index = scratch.content_index;
520 |         match scratch.kind {
