574 |     fn apply_message_delta(
575 |         &mut self,
576 |         payload: &serde_json::Value,
577 |         prod: &mut AssistantMessageEventStreamProducer,
578 |     ) {
579 |         let _ = prod; // message_delta never pushes events; it mutates output only.
580 |                       // `delta.stop_reason` → mapStopReason + rawStopReason.
581 |         if let Some(stop_reason) = payload
582 |             .pointer("/delta/stop_reason")
583 |             .and_then(|v| v.as_str())
584 |         {
585 |             self.output.raw_stop_reason = Some(stop_reason.to_string());
586 |             let stop_details = payload.pointer("/delta/stop_details");
587 |             match map_stop_reason(stop_reason, stop_details) {
588 |                 Ok(MappedStop {
589 |                     stop_reason,
590 |                     error_message,
591 |                 }) => {
592 |                     self.output.stop_reason = stop_reason;
593 |                     if let Some(msg) = error_message {
594 |                         self.output.error_message = Some(msg);
595 |                     }
596 |                 }
597 |                 Err(e) => {
598 |                     // TS throws on unhandled stop reasons; the Rust port records
599 |                     // it as an error message + Error stop_reason so the stream
600 |                     // still terminates (the provider loop converts the
601 |                     // post-stream Error check).
602 |                     self.output.stop_reason = StopReason::Error;
603 |                     self.output.error_message = Some(e.to_string());
604 |                 }
605 |             }
606 |         }
607 | 
608 |         // Usage update — only fields that are present (not null), mirroring the
609 |         // TS field-by-field null checks. Preserves message_start input_tokens
610 |         // when the proxy omits them here.
611 |         if let Some(usage) = payload.get("usage") {
612 |             if let Some(v) = usage.get("input_tokens").and_then(|v| v.as_i64()) {
613 |                 self.output.usage.input = v;
614 |             }
615 |             if let Some(v) = usage.get("output_tokens").and_then(|v| v.as_i64()) {
616 |                 self.output.usage.output = v;
617 |             }
618 |             if let Some(v) = usage
619 |                 .get("cache_read_input_tokens")
620 |                 .and_then(|v| v.as_i64())
621 |             {
622 |                 self.output.usage.cache_read = v;
623 |             }
624 |             if let Some(v) = usage
625 |                 .get("cache_creation_input_tokens")
626 |                 .and_then(|v| v.as_i64())
627 |             {
628 |                 self.output.usage.cache_write = v;
629 |             }
630 |             // Reasoning tokens — a subset of output_tokens, reported via
631 |             // `output_tokens_details.thinking_tokens` (the SDK type omits the
632 |             // field; the TS reads it through a narrow cast). Mirrors that.
633 |             if let Some(thinking_tokens) = usage
634 |                 .pointer("/output_tokens_details/thinking_tokens")
635 |                 .and_then(|v| v.as_i64())
636 |             {
637 |                 self.output.usage.reasoning = Some(thinking_tokens);
638 |             }
639 |         }
640 |         // Anthropic doesn't provide total_tokens; recompute from components
641 |         // unconditionally (mirrors TS line 741, OUTSIDE the `if (event.usage)`
642 |         // block). When usage is absent the components are unchanged, so this
643 |         // is a no-op — but it stays faithful to the source's control flow.
644 |         self.output.usage.total_tokens = self.output.usage.input
645 |             + self.output.usage.output
646 |             + self.output.usage.cache_read
647 |             + self.output.usage.cache_write;
648 |     }
649 | }
