651 | /// The result of mapping an Anthropic stop reason. Mirrors the TS return shape
652 | /// `{ stopReason, errorMessage? }`.
653 | pub struct MappedStop {
654 |     pub stop_reason: StopReason,
655 |     pub error_message: Option<String>,
656 | }
657 | 
658 | /// Map an Anthropic `stop_reason` to pi's `StopReason`, optionally carrying an
659 | /// error message (`refusal`/`sensitive`). Mirrors TS `mapStopReason`.
660 | ///
661 | /// Returns `Err(AiError::Provider)` for an unhandled stop reason so the caller
662 | /// can surface it; the TS source `throw`s, which the Rust port translates to an
663 | /// `AiError` rather than a panic.
664 | pub fn map_stop_reason(
665 |     reason: &str,
666 |     stop_details: Option<&serde_json::Value>,
667 | ) -> Result<MappedStop, AiError> {
668 |     match reason {
669 |         "end_turn" => Ok(MappedStop {
670 |             stop_reason: StopReason::Stop,
671 |             error_message: None,
672 |         }),
673 |         "max_tokens" => Ok(MappedStop {
674 |             stop_reason: StopReason::Length,
675 |             error_message: None,
676 |         }),
677 |         "tool_use" => Ok(MappedStop {
678 |             stop_reason: StopReason::ToolUse,
679 |             error_message: None,
680 |         }),
681 |         "refusal" => {
682 |             let explanation = stop_details
683 |                 .and_then(|d| d.get("explanation"))
684 |                 .and_then(|v| v.as_str())
685 |                 .map(|s| s.to_string())
686 |                 .unwrap_or_else(|| "The model refused to complete the request".to_string());
687 |             Ok(MappedStop {
688 |                 stop_reason: StopReason::Error,
689 |                 error_message: Some(explanation),
690 |             })
691 |         }
692 |         // pause_turn / stop_sequence both collapse to Stop (mirrors TS).
693 |         "pause_turn" | "stop_sequence" => Ok(MappedStop {
694 |             stop_reason: StopReason::Stop,
695 |             error_message: None,
696 |         }),
697 |         "sensitive" => Ok(MappedStop {
698 |             stop_reason: StopReason::Error,
699 |             error_message: Some("Provider stopped with: sensitive".to_string()),
700 |         }),
701 |         other => Err(AiError::Provider {
702 |             code: "unhandled_stop_reason".to_string(),
703 |             message: format!("Unhandled stop reason: {other}"),
704 |         }),
705 |     }
706 | }
