200 | /// Parse a key event from terminal input data.
201 | /// Returns the parsed key if the data represents a key event.
202 | pub fn parse_key(data: &str) -> Option<Key> {
203 |     if data.is_empty() {
204 |         return None;
205 |     }
206 | 
207 |     // Single character (including control characters)
208 |     if data.len() == 1 {
209 |         let c = data.chars().next()?;
210 |         return parse_single_char(c);
211 |     }
212 | 
213 |     // Check for escape sequences
214 |     if data.starts_with('\x1b') {
215 |         return parse_escape_sequence(data);
216 |     }
217 | 
218 |     None
219 | }
