221 | /// Parse a single character key.
222 | fn parse_single_char(c: char) -> Option<Key> {
223 |     let code = c as u32;
224 | 
225 |     // Control characters
226 |     match code {
227 |         0x00 => return Some(Key::new("ctrl+space")),
228 |         0x01..=0x07 => {
229 |             // Ctrl+A to Ctrl+G
230 |             let letter = (b'a' + (code - 1) as u8) as char;
231 |             return Some(Key::new(KeyHelper::ctrl(&letter.to_string())));
232 |         }
233 |         0x08 => return Some(Key::new(KeyHelper::BACKSPACE)), // Ctrl+H = Backspace
234 |         0x09 => return Some(Key::new(KeyHelper::TAB)),       // Ctrl+I = Tab
235 |         0x0a | 0x0d => return Some(Key::new(KeyHelper::ENTER)), // Ctrl+J/M = Enter
236 |         0x0b..=0x1a => {
237 |             // Ctrl+K to Ctrl+Z
238 |             let letter = (b'k' + (code - 0x0b) as u8) as char;
239 |             return Some(Key::new(KeyHelper::ctrl(&letter.to_string())));
240 |         }
241 |         0x1b => return Some(Key::new(KeyHelper::ESCAPE)),
242 |         0x7f => return Some(Key::new(KeyHelper::BACKSPACE)), // DEL
243 |         _ => {}
244 |     }
245 | 
246 |     // Regular printable character
247 |     if c >= ' ' && c != '\x7f' {
248 |         let key_str = c.to_string();
249 |         if key_str.chars().all(|c| c.is_uppercase()) {
250 |             Some(Key::new(key_str.to_lowercase()).with_modifier(Modifier::Shift))
251 |         } else {
252 |             Some(Key::new(key_str))
253 |         }
254 |     } else {
255 |         None
256 |     }
257 | }
