259 | /// Parse an escape sequence.
260 | fn parse_escape_sequence(data: &str) -> Option<Key> {
261 |     let bytes = data.as_bytes();
262 | 
263 |     // CSI sequence: ESC [
264 |     if bytes.len() >= 3 && bytes[1] == b'[' {
265 |         return parse_csi_sequence(data);
266 |     }
267 | 
268 |     // SS3 sequence: ESC O
269 |     if bytes.len() >= 3 && bytes[1] == b'O' {
270 |         return parse_ss3_sequence(data);
271 |     }
272 | 
273 |     // Alt + key (ESC followed by single char)
274 |     if bytes.len() == 2 {
275 |         let c = bytes[1] as char;
276 |         let mut key = parse_single_char(c)?;
277 |         key.modifiers.push(Modifier::Alt);
278 |         return Some(key);
279 |     }
280 | 
281 |     None
282 | }
