284 | /// Parse a CSI sequence.
285 | fn parse_csi_sequence(data: &str) -> Option<Key> {
286 |     let bytes = data.as_bytes();
287 | 
288 |     // Find the final byte (0x40-0x7E)
289 |     let final_idx = bytes.iter().rposition(|&b| (0x40..=0x7E).contains(&b))?;
290 |     let final_byte = bytes[final_idx];
291 | 
292 |     // Parse parameters (between [ and final byte)
293 |     let params_str = &data[2..final_idx];
294 |     let params: Vec<u32> = params_str
295 |         .split(';')
296 |         .filter_map(|s| s.parse().ok())
297 |         .collect();
298 | 
299 |     // Decode modifiers
300 |     let mut modifiers = Vec::new();
301 |     if params.len() >= 2 {
302 |         let mod_byte = params[1] as u8;
303 |         if mod_byte & MOD_CTRL != 0 {
304 |             modifiers.push(Modifier::Ctrl);
305 |         }
306 |         if mod_byte & MOD_SHIFT != 0 {
307 |             modifiers.push(Modifier::Shift);
308 |         }
309 |         if mod_byte & MOD_ALT != 0 {
310 |             modifiers.push(Modifier::Alt);
311 |         }
312 |         if mod_byte & MOD_SUPER != 0 {
313 |             modifiers.push(Modifier::Super);
314 |         }
315 |     }
316 | 
317 |     // Determine event type (Kitty protocol)
318 |     let event_type = if params.len() >= 2 {
319 |         let event_type_code = params.get(0).copied().unwrap_or(1);
320 |         match event_type_code {
321 |             1 => KeyEventType::Press,
322 |             2 => KeyEventType::Repeat,
323 |             3 => KeyEventType::Release,
324 |             _ => KeyEventType::Press,
325 |         }
326 |     } else {
327 |         KeyEventType::Press
328 |     };
329 | 
330 |     // Parse key based on final byte and parameters
331 |     let key = match final_byte {
332 |         b'~' => parse_csi_tilde_key(&params)?,
333 |         b'A' => Key::new(KeyHelper::UP),
334 |         b'B' => Key::new(KeyHelper::DOWN),
335 |         b'C' => Key::new(KeyHelper::RIGHT),
336 |         b'D' => Key::new(KeyHelper::LEFT),
337 |         b'E' => Key::new("begin"),
338 |         b'F' => Key::new(KeyHelper::END),
339 |         b'H' => Key::new(KeyHelper::HOME),
340 |         b'Z' => Key::new(KeyHelper::TAB).with_modifier(Modifier::Shift),
341 |         b'u' => {
342 |             // Kitty CSI-u: ESC [ code ; modifiers u
343 |             decode_kitty_printable(&params)?
344 |         }
345 |         _ => return None,
346 |     };
347 | 
348 |     Some(key).map(|mut k| {
349 |         k.modifiers.extend(modifiers);
350 |         k.event_type = event_type;
351 |         k
352 |     })
353 | }
