355 | /// Parse CSI tilde key (~ sequences).
356 | fn parse_csi_tilde_key(params: &[u32]) -> Option<Key> {
357 |     let code = params.first().copied().unwrap_or(0);
358 |     match code {
359 |         1 => Some(Key::new(KeyHelper::F1)),
360 |         2 => Some(Key::new(KeyHelper::INSERT)),
361 |         3 => Some(Key::new(KeyHelper::DELETE)),
362 |         4 => Some(Key::new(KeyHelper::END)),
363 |         5 => Some(Key::new(KeyHelper::PAGE_UP)),
364 |         6 => Some(Key::new(KeyHelper::PAGE_DOWN)),
365 |         7 => Some(Key::new(KeyHelper::HOME)),
366 |         8 => Some(Key::new(KeyHelper::END)),
367 |         11..=14 => Some(Key::new(KeyHelper::F1)),
368 |         15..=18 => Some(Key::new(KeyHelper::F5)),
369 |         19..=20 => Some(Key::new(KeyHelper::F9)),
370 |         21..=24 => Some(Key::new(KeyHelper::F11)),
371 |         _ => None,
372 |     }
373 | }
374 | 
375 | /// Parse SS3 sequence (ESC O sequences).
376 | fn parse_ss3_sequence(data: &str) -> Option<Key> {
377 |     let final_char = data.chars().nth(2)?;
378 |     match final_char {
379 |         'A' => Some(Key::new(KeyHelper::UP)),
380 |         'B' => Some(Key::new(KeyHelper::DOWN)),
381 |         'C' => Some(Key::new(KeyHelper::RIGHT)),
382 |         'D' => Some(Key::new(KeyHelper::LEFT)),
383 |         'E' => Some(Key::new("begin")),
384 |         'F' => Some(Key::new(KeyHelper::END)),
385 |         'H' => Some(Key::new(KeyHelper::HOME)),
386 |         'P' => Some(Key::new(KeyHelper::F1)),
387 |         'Q' => Some(Key::new(KeyHelper::F2)),
388 |         'R' => Some(Key::new(KeyHelper::F3)),
389 |         'S' => Some(Key::new(KeyHelper::F4)),
390 |         _ => None,
391 |     }
392 | }
393 | 
394 | /// Decode Kitty printable character (CSI-u).
395 | fn decode_kitty_printable(params: &[u32]) -> Option<Key> {
396 |     let code = params.first().copied().unwrap_or(0);
397 | 
398 |     // Printable ASCII
399 |     if code >= 32 && code < 127 {
400 |         let c = code as u8 as char;
401 |         return Some(Key::new(c.to_string()));
402 |     }
403 | 
404 |     // Decode special characters
405 |     match code {
406 |         57399 => Some(Key::new(KeyHelper::INSERT)),
407 |         57414 => Some(Key::new(KeyHelper::DELETE)),
408 |         57415 => Some(Key::new(KeyHelper::PAGE_UP)),
409 |         57416 => Some(Key::new(KeyHelper::PAGE_DOWN)),
410 |         57399..=57428 => {
411 |             // Function keys in Kitty
412 |             let offset = code - 57399;
413 |             let fn_key = match offset {
414 |                 0 => "f1",
415 |                 1 => "f2",
416 |                 2 => "f3",
417 |                 3 => "f4",
418 |                 4 => "f5",
419 |                 5 => "f6",
420 |                 6 => "f7",
421 |                 7 => "f8",
422 |                 8 => "f9",
423 |                 9 => "f10",
424 |                 10 => "f11",
425 |                 11 => "f12",
426 |                 _ => return None,
427 |             };
428 |             Some(Key::new(fn_key))
429 |         }
430 |         _ => None,
431 |     }
432 | }
