1 | //! Word navigation utilities for text editing.
2 | //!
3 | //! Provides functions for finding word boundaries in text.
4 | 
5 | /// Characters that are considered word boundaries.
6 | const WORD_BOUNDARY_CHARS: &[char] = &[
7 |     ' ', '\t', '\n', '\r', '-', '_', '.', '/', ':', '\\', '(', ')', '[', ']', '{', '}', '<', '>',
8 |     '=', '+', '*', '&', '|', '!', '@', '#', '$', '%', '^', '~', '`', ',', ';', '"', '\'',
9 | ];
10 | 
11 | /// Check if a character is a word boundary.
12 | pub fn is_word_boundary(c: char) -> bool {
13 |     WORD_BOUNDARY_CHARS.contains(&c)
14 | }
15 | 
16 | /// Check if a character is a word character.
17 | pub fn is_word_char(c: char) -> bool {
18 |     !is_word_boundary(c)
19 | }
20 | 
21 | /// Find the start of the previous word from the given position.
22 | /// Returns the index of the start of the previous word.
23 | pub fn find_word_backward(text: &str, position: usize) -> usize {
24 |     if position == 0 {
25 |         return 0;
26 |     }
27 | 
28 |     let chars: Vec<char> = text.chars().collect();
29 |     let mut index = position.saturating_sub(1);
30 | 
31 |     // Skip any trailing whitespace or boundary characters
32 |     while index > 0 && (chars[index].is_whitespace() || is_word_boundary(chars[index])) {
33 |         index -= 1;
34 |     }
35 | 
36 |     // Now find the start of this word
37 |     while index > 0 && is_word_char(chars[index.saturating_sub(1)]) {
38 |         index -= 1;
39 |     }
40 | 
41 |     index
42 | }
43 | 
44 | /// Find the start of the next word from the given position.
45 | /// Returns the index of the start of the next word.
46 | pub fn find_word_forward(text: &str, position: usize) -> usize {
