365 | pub fn get_webp_dimensions(data: &[u8]) -> Option<ImageDimensions> {
366 |     if data.len() < 30 {
367 |         return None;
368 |     }
369 | 
370 |     // RIFF....WEBP
371 |     if &data[0..4] != b"RIFF" || &data[8..12] != b"WEBP" {
372 |         return None;
373 |     }
374 | 
375 |     // Check for VP8 chunk
376 |     if &data[12..16] == b"VP8 " {
377 |         // VP8 format
378 |         let width = u16::from_le_bytes([data[26], data[27]]) as u32 & 0x3FFF;
379 |         let height = u16::from_le_bytes([data[28], data[29]]) as u32 & 0x3FFF;
380 |         return Some(ImageDimensions { width, height });
381 |     }
382 | 
383 |     // Check for VP8L (lossless)
384 |     if &data[12..16] == b"VP8L" {
385 |         // VP8L format - dimensions are in a 28-bit field
386 |         if data.len() < 21 {
387 |             return None;
388 |         }
